<script setup>
import PublicLayout from '../../Layouts/PublicLayout.vue';
import { Head, useForm } from '@inertiajs/vue3';
const props=defineProps({account:Object,payments:Array,paymentEnabled:Boolean,paystackEnabled:Boolean});
const plan=useForm({plan:props.account.plan||'annual'});
const pay=useForm({plan:props.account.plan||'annual'});
const money=v=>'₦'+Number(v||0).toLocaleString('en-NG',{maximumFractionDigits:2});
const label=s=>({up_to_date:'Up to date',due:'Payment due',overdue:'Overdue',exempt:'Exempt'}[s]||s);
function submit(){pay.post('/dues/paystack/initialize');}
</script>
<template><PublicLayout><Head title="Membership Dues"/><section class="bg-[#F7F9F7] py-10"><div class="mx-auto max-w-5xl px-5"><div class="mb-6"><p class="text-xs font-bold uppercase tracking-widest text-[#006B3C]">Member account</p><h1 class="mt-2 text-3xl font-extrabold text-[#00351F]">Membership Dues</h1><p class="mt-2 text-sm text-gray-600">Manage your BBHS annual or monthly membership contributions.</p></div><div class="rounded-2xl border bg-white p-6 shadow-sm"><div class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-sm text-gray-500">Current payment status</p><h2 class="mt-1 text-2xl font-extrabold text-[#00351F]">{{label(account.status)}}</h2></div><span class="rounded-full bg-[#EEF8F2] px-4 py-2 text-sm font-bold text-[#006B3C]">{{account.status==='up_to_date'?'Paid':account.status==='exempt'?'Exempt':'Action required'}}</span></div><div class="mt-6 grid gap-4 sm:grid-cols-3"><div><p class="text-xs text-gray-500">Commencement date</p><p class="mt-1 font-bold">{{account.commencement_date||'Not set'}}</p></div><div><p class="text-xs text-gray-500">Paid through</p><p class="mt-1 font-bold">{{account.paid_through||'—'}}</p></div><div><p class="text-xs text-gray-500">Next due date</p><p class="mt-1 font-bold">{{account.next_due_at||'—'}}</p></div></div></div><div class="mt-6 grid gap-6 md:grid-cols-2"><div class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-extrabold text-[#00351F]">Choose payment frequency</h2><form @submit.prevent="plan.put('/dues/plan')" class="mt-5 space-y-4"><label class="flex cursor-pointer gap-3 rounded-xl border p-4"><input v-model="plan.plan" type="radio" value="annual"/><span><b>Annual payment</b><span class="block text-sm text-gray-500">₦12,500 once every 12 months</span></span></label><label class="flex cursor-pointer gap-3 rounded-xl border p-4"><input v-model="plan.plan" type="radio" value="monthly"/><span><b>Monthly payment</b><span class="block text-sm text-gray-500">₦1,050 per month (₦12,600 over 12 months)</span></span></label><button class="rounded-lg border border-[#006B3C] px-4 py-2 text-sm font-bold text-[#006B3C]" :disabled="plan.processing">Save preference</button></form></div><div class="rounded-2xl border bg-white p-6"><h2 class="text-xl font-extrabold text-[#00351F]">Make a payment</h2><p class="mt-2 text-sm text-gray-600">Select the period you wish to pay for. Payments are verified before your account is updated.</p><p v-if="!paymentEnabled" class="mt-4 rounded-lg bg-amber-50 p-3 text-sm text-amber-800">Payment will be available after your membership is approved.</p><p v-else-if="account.exempt" class="mt-4 rounded-lg bg-green-50 p-3 text-sm text-green-800">Your dues are currently exempted.</p><form v-else @submit.prevent="submit" class="mt-5"><select v-model="pay.plan" class="w-full rounded-lg border-gray-300"><option value="annual">Annual — ₦12,500</option><option value="monthly">Monthly — ₦1,050</option></select><button :disabled="!paystackEnabled||!paymentEnabled||pay.processing" class="mt-4 w-full rounded-lg bg-[#006B3C] px-5 py-3 font-bold text-white disabled:opacity-50">{{paystackEnabled?'Continue to Paystack':'Online payment not configured'}}</button><p v-if="!paystackEnabled" class="mt-2 text-xs text-gray-500">The Association has not configured Paystack credentials yet.</p></form></div></div><div class="mt-6 rounded-2xl border bg-white p-6"><h2 class="text-xl font-extrabold text-[#00351F]">Payment history</h2><div v-if="payments.length" class="mt-4 overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b text-gray-500"><th class="py-3">Date</th><th>Reference</th><th>Plan</th><th>Amount</th><th>Status</th></tr></thead><tbody><tr v-for="p in payments" :key="p.id" class="border-b"><td class="py-3">{{p.paid_at||p.created_at}}</td><td>{{p.reference}}</td><td class="capitalize">{{p.period_type}}</td><td>{{money(p.amount)}}</td><td class="capitalize">{{p.status}}</td></tr></tbody></table></div><p v-else class="mt-3 text-sm text-gray-500">No dues payments recorded yet.</p></div></div></section></PublicLayout></template>
